mapper.select:

WHERE

AND t.deleted_at IS NULL AND LOCATE(#{query}, t.title) > 0

  AND (t.created_by = #{access.userId} OR t.owner_user_id = #{access.userId})
  AND t.team_id IS NOT NULL

AND t.team_id = #{team}

  AND t.status IN ('pending','in_progress')
  AND t.status = #{state}


  AND (t.updated_at < #{after.time} OR (t.updated_at = #{after.time} AND t.id < #{after.id}))

ORDER BY t.updated_at DESC, t.id DESC LIMIT #{limit}
